package io.odysz.reflect;

import java.util.HashMap;

import io.odysz.anson.Anson;

/**
 * The ASTs of a module's types, generated by anson.reflect (a Maven plugin) into the module's jar
 * as anson-types.json, for code generators (semantier_gen) resolving Java imports.
 * 
 * <p>See anson.reflect's TypeScanner for an example.</p>
 * 
 * @since 1.2.0
 */
public class AnsonTypes extends Anson {
	/** groupId:artifactId:version */
	public String module;

	/** {qualified name: AST}, the module's own types: public classes and non-private nested types */
	public HashMap<String, AnsonAst> asts;

	/**
	 * {qualified name: groupId:artifactId:version}, where a used type, not of this module, is found.
	 * JDK types and types not found in the dependencies are not listed.
	 */
	public HashMap<String, String> dependencies;

	public AnsonTypes() { }

	public AnsonTypes(String module) {
		this.module = module;
		this.asts = new HashMap<String, AnsonAst>();
		this.dependencies = new HashMap<String, String>();
	}
}
